class Solution { public int[][] intervalIntersections(int[][] first, int[][] second) { java.util.ArrayList<int[]> list=new java.util.ArrayList<>();int i=0,j=0;while(i<first.length&&j<second.length){int l=Math.max(first[i][0],second[j][0]),h=Math.min(first[i][1],second[j][1]);if(l<=h)list.add(new int[]{l,h});if(first[i][1]<second[j][1])i++;else j++;}return list.toArray(new int[0][]); } }
